import { parseEntityReviewCorpus, entityReviewInput } from '/private/tmp/omk-entity-v7-pp96jlnb/sealed-runtime/dist-scripts/bench/entity-review-corpus.js';

const root = dirname(fileURLToPath(import.meta.url));
const load = path => JSON.parse(readFileSync(resolve(root, path), 'utf8'));
const manifest = load('frozen/manifest.json');
const corpus = parseEntityReviewCorpus(readFileSync(resolve(root, 'frozen/corpus.json'), 'utf8'));
const inputs = load('frozen/inputs.json');
const authorText = readFileSync(resolve(root, 'frozen/self-review.json'), 'utf8');
if (manifest.measurementId !== 'sha256:108acc6c8abf6fd382651b074576268ef9ad2987b54aeef747a541faea382976'
  || EXTRACTION_PROMPT_VERSION !== 'knowledge-extraction-v7' || reviewDigest(EXTRACTION_PROMPT) !== manifest.promptHash
  || authorReviewStatus(authorText, corpus, manifest.measurementId).status !== 'completed') throw new Error('Frozen identity/author review mismatch.');
if (inputs.length !== 42 || corpus.cases.length !== 42) throw new Error('Expected exactly 42 frozen cases.');
for (const sample of corpus.cases) {
  const input = inputs.find(value => value.caseId === sample.caseId);
  if (!input || input.inputDigest !== reviewDigest(JSON.stringify(entityReviewInput(sample)))
    || JSON.stringify(input.input) !== JSON.stringify(entityReviewInput(sample))) throw new Error('Frozen input mismatch.');
}
const selectedCaseIds = ["dev-session-properties", "dev-unconfirmed-memory", "dev-confirmed-memory", "dev-session-atomic-negation", "held-product-name-substring", "held-collective-norm"];
const selectedInputs = inputs.filter(value => selectedCaseIds.includes(value.caseId));
if (selectedInputs.length !== 6) throw new Error('Pilot selection mismatch.');
const plan = { measurementId: manifest.measurementId, executor: 'codex', model: 'gpt-6.1-sol', repeats: 1,
  caseCount: selectedInputs.length, selectedCaseIds, maxCalls: 6, concurrency: 2, retries: 0,
  scheduling: 'Single diagnostic pass; development and validation each run serially in parallel.',
  usdCost: 'unknown', effort: 'executor default, not explicitly set',
  backendRevision: 'not reported', sourceCommit: '0242f950854f057447407718cbe6ba7f6fed8b00',
  allowedData: 'Frozen source excerpts and limitations, plus exact production v7 prompt. No gold, review criteria or previous output.',
  authorization: '2026-10-11 用户回复「好」，同意已提出的 6 个新合成场景单轮效果复验；沿用现有 Codex gpt-6.1-sol，最多 6 次，无自动重试，结果由实现 Agent 逐例复核。',
  captureDriverDigest: `sha256:${createHash('sha256').update(readFileSync(fileURLToPath(import.meta.url))).digest('hex')}` };
const args = process.argv.slice(2);
if (args.length === 0) { console.log(JSON.stringify({ ...plan, mode: 'dry-run', modelCalls: 0 }, null, 2)); }
else if (args.length !== 1 || args[0] !== '--execute') throw new Error('Only --execute starts the explicitly authorized 6-call pilot plan.');
else {
  const output = resolve(root, 'captures-pilot');
  mkdirSync(output); // One invocation only; never overwrite or resume/retry this run.
  const saveNew = (name, value) => writeFileSync(resolve(output, name), JSON.stringify(value, null, 2), { flag: 'wx' });
  const replace = (name, value) => {
    const path = resolve(output, name); const temporary = `${path}.pending`;
    writeFileSync(temporary, JSON.stringify(value, null, 2), { flag: 'wx' }); renameSync(temporary, path);
  };
  const startedAt = new Date().toISOString();
  const state = { ...plan, startedAt, status: 'running', attempted: 0, recorded: 0, executorInvocations: 0 };
  saveNew('plan.json', plan); saveNew('manifest.json', state);
  saveNew('prompt.json', { version: EXTRACTION_PROMPT_VERSION, prompt: EXTRACTION_PROMPT });
  const controller = new AbortController();
  const abort = () => controller.abort(); process.once('SIGINT', abort); process.once('SIGTERM', abort);
  const execute = createExecutor('codex');
  const groups = ['development', 'validation'].map(split => ({ captureVersion: 'omk-entity-captures/v1',
    measurementId: manifest.measurementId, split, repeats: 1, startedAt, executor: plan.executor, model: plan.model, records: [] }));
  for (const group of groups) saveNew(`${group.split}.json`, group);
  const worker = async (group, repeat) => {
    for (const input of selectedInputs.filter(value => value.split === group.split)) {
      if (controller.signal.aborted) break;
      const id = `${repeat}-${input.caseId}`;
      let runtime;
      const model = configuredExtractionModel(plan.executor, plan.model, async invocation => {
        if (invocation.system !== EXTRACTION_PROMPT || invocation.prompt !== JSON.stringify(input.input)) throw new Error('Sent bytes differ from frozen inputs.');
        state.executorInvocations = (state.executorInvocations ?? 0) + 1;
        if (state.executorInvocations > 6) throw new Error('Invocation limit exceeded.');
        replace('manifest.json', state);
        runtime = await execute(invocation);
        saveNew(`${id}.runtime.json`, runtime); // Preserve full executor result even if the adapter rejects it.
        return runtime;
      });
      state.attempted += 1; replace('manifest.json', state);
      const callStartedAt = new Date().toISOString(); const started = performance.now();
      let result;
      try {
        const generated = await model.generate(EXTRACTION_PROMPT, JSON.stringify(input.input), controller.signal);
        result = { captureStatus: 'output', output: generated.output, durationMs: generated.durationMs,
          usage: { inputTokens: runtime.inputTokens, outputTokens: runtime.outputTokens, cacheReadTokens: runtime.cacheReadTokens,
            cacheCreationTokens: runtime.cacheCreationTokens, tokenUsageReportedByExecutor: runtime.tokenUsageReportedByExecutor ?? true,
            costReportedByExecutor: runtime.costReportedByExecutor ?? true },
          ...(runtime.costReportedByExecutor === false ? {} : { costUSD: runtime.costUSD }) };
      } catch (error) {
        result = { captureStatus: runtime?.stopReason === 'interrupted' || (!runtime && controller.signal.aborted) ? 'cancelled' : 'call_failure',
          failure: error instanceof Error ? error.message : String(error),
          ...(runtime ? { durationMs: runtime.durationMs } : {}),
          ...(runtime && runtime.costReportedByExecutor !== false ? { costUSD: runtime.costUSD } : {}) };
      }
      const record = { caseId: input.caseId, repeat, inputDigest: input.inputDigest, result };
      saveNew(`${id}.json`, { ...record, callStartedAt, finishedAt: new Date().toISOString(), wallClockDurationMs: performance.now() - started });
      group.records.push(record); replace(`${group.split}.json`, group);
      state.recorded += 1; replace('manifest.json', state);
      console.log(`[${state.recorded}/6] round ${repeat} ${input.caseId}: ${result.captureStatus}; structural/semantic checks pending`);
    }
  };
  try {
    for (let repeat = 1; repeat <= 1 && !controller.signal.aborted; repeat += 1) {
      const results = await Promise.allSettled(groups.map(async group => {
        try { await worker(group, repeat); } catch (error) { controller.abort(); throw error; }
      }));
      const fatal = results.find(value => value.status === 'rejected');
      if (fatal) throw fatal.reason;
      console.log(`Round ${repeat} capture finished; no outputs used as input to later calls.`);
    }
    state.status = controller.signal.aborted ? 'cancelled' : state.recorded === 11 ? 'captured' : 'incomplete';
    state.finishedAt = new Date().toISOString(); replace('manifest.json', state);
    if (state.status !== 'captured') process.exitCode = 1;
  } catch (error) {
    state.status = 'local_failure'; state.failure = String(error); state.finishedAt = new Date().toISOString();
    replace('manifest.json', state); throw error;
  } finally { process.removeListener('SIGINT', abort); process.removeListener('SIGTERM', abort); }
}

